function validatePhoneNumber(phone) {
  // Remove all non-digit characters (spaces, dashes, parentheses, +, etc.)
  const digitsOnly = phone.replace(/[^0-9]/g, '');

  // Check if exactly 10 digits remain
  if (digitsOnly.length === 10) {
    return true;   // valid
  } else {
    return false;  // invalid
  }
}

// Test cases
console.log(validatePhoneNumber('01712345678'));   // false (11 digits)
console.log(validatePhoneNumber('1712345678'));    // true (10 digits)
console.log(validatePhoneNumber('171-234-5678'));  // true (non-digits removed → 10)
console.log(validatePhoneNumber('+1(234)567890')); // false (11 digits)
console.log(validatePhoneNumber('17-12-34'));      // false (7 digits)

// Note: Bangladeshi mobile numbers have 11 digits (01XXXXXXXXX)
// For Bangladesh, change === 10 to === 11

